// Adapted from https://huggingface.co/kernels/webgpu-kernels/ai.onnx.Conv/resolve/7b19a1ea4fd2abef3203991ca933405f12cfcc62/build/webgpu/conv-1x1-gemm-tiled-reg.wgsl.jinja
// Upstream Apache-2.0; integration MIT (https://github.com/barhanc/wgpu-executorch).
// Register-blocked batched matrix product:
// C[b] (M x N) = A (M x K) * B[b] (K x N). Workgroup lanes compute TM x TN
// micro-tiles. The defaults use a 16x8 lane grid with an 8x4 micro-tile over a
// 64x64 output tile. A is shared across the batch; B and C use the dispatch.z
// batch offset. Accumulation is f32; an optional epilogue applies configured
// bias, residual, and activation terms in the accumulator domain on store.
// Every matrix dimension is bounds-checked.
// f16 operands remain packed in workgroup memory and widen only at the FMA site;
// the f32 accumulation order is retained while shared traffic is halved.
//
// Both shared tiles are stored as vec4 groups along the axis each lane consumes
// contiguously: tileA groups four K values for one output row, tileB groups four
// N columns for one K. One micro-tile step therefore reads TM + 4 vector words
// instead of 4 * (TM + TN) scalars, so a shared word feeds four times as many
// FMAs and the K loop runs four accumulation steps per iteration.

@group(0) @binding(0) var<storage, read_write> y: array<f32>;
@group(0) @binding(1) var<storage, read> xm: array<f32>;
@group(0) @binding(2) var<storage, read> w: array<f32>;
@group(0) @binding(3) var<storage, read> bias: array<f32>;
struct Params { M: u32, K: u32, N: u32, has_bias: u32 }
@group(0) @binding(4) var<uniform> params: Params;










const BK: u32 = 16u;
const BM: u32 = 64u;
const BN: u32 = 64u;
const TM: u32 = 8u;
const TN: u32 = 4u;
const WG_X: u32 = 16u;
const WG_SIZE: u32 = 128u;
// Vector words per tile row: A groups K, B groups N.
const AK_VECS: u32 = BK / 4u;
const BN_VECS: u32 = BN / 4u;

// implicitIm2col leaves B unmaterialized. While staging a tile, the kernel
// decodes each (k, n) column-matrix coordinate into a raw NCHW input address.
// Overlapping windows may reread input values, trading address arithmetic and
// repeated input loads for writing and rereading an expanded column matrix.


















fn store_out(m: u32, n: u32, yBase: u32, raw: f32) {
  if (m >= params.M || n >= params.N) {
    return;
  }
  var v = raw;

  if (params.has_bias != 0u) { v = v + f32(bias[m]); }

  y[yBase + m * params.N + n] = f32(v);
}


var<workgroup> tileA: array<array<vec4<f32>, AK_VECS>, BM>;
var<workgroup> tileB: array<array<vec4<f32>, BN_VECS>, BK>;





@compute @workgroup_size(16, 8, 1)
fn main(
  @builtin(workgroup_id) wg: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>
) {
  let M = params.M;
  let K = params.K;
  let N = params.N;
  let mBase = wg.y * BM;
  let nBase = wg.x * BN;

  let batch = wg.z;


  let xBatchBase = batch * K * N;

  let li = lid.y * WG_X + lid.x;

  // The statically named accumulator vectors form TM independent FMA chains.

  var acc0 = vec4<f32>(0.0);

  var acc1 = vec4<f32>(0.0);

  var acc2 = vec4<f32>(0.0);

  var acc3 = vec4<f32>(0.0);

  var acc4 = vec4<f32>(0.0);

  var acc5 = vec4<f32>(0.0);

  var acc6 = vec4<f32>(0.0);

  var acc7 = vec4<f32>(0.0);



  let numTiles = (K + BK - 1u) / BK;

  for (var kt: u32 = 0u; kt < numTiles; kt = kt + 1u) {

    let kBase = kt * BK;


    for (var linear = li; linear < BM * AK_VECS; linear += WG_SIZE) {
      let ar = linear / AK_VECS;
      let ac4 = linear % AK_VECS;
      let am = mBase + ar;
      let ak = kBase + ac4 * 4u;
      var av = vec4<f32>(f32(0.0));
      if (am < M) {
        let aBase = am * K + ak;
        if (ak + 3u < K) {
          av = vec4<f32>(f32(w[aBase]), f32(w[aBase + 1u]), f32(w[aBase + 2u]), f32(w[aBase + 3u]));
        } else {
          for (var t = 0u; t < 4u; t = t + 1u) {
            if (ak + t < K) {
              av[t] = f32(w[aBase + t]);
            }
          }
        }
      }
      tileA[ar][ac4] = av;
    }


    for (var linear = li; linear < BK * BN_VECS; linear += WG_SIZE) {
      let br = linear / BN_VECS;
      let bc4 = linear % BN_VECS;
      let bk = kBase + br;
      let bn = nBase + bc4 * 4u;
      var bvec = vec4<f32>(f32(0.0));
      if (bk < K) {
        let bBase = xBatchBase + bk * N + bn;
        if (bn + 3u < N) {
          bvec = vec4<f32>(f32(xm[bBase]), f32(xm[bBase + 1u]), f32(xm[bBase + 2u]), f32(xm[bBase + 3u]));
        } else {
          for (var t = 0u; t < 4u; t = t + 1u) {
            if (bn + t < N) {
              bvec[t] = f32(xm[bBase + t]);
            }
          }
        }
      }
      tileB[br][bc4] = bvec;
    }

    workgroupBarrier();
    // One iteration consumes four K steps: TM vector words of A and four of B
    // cover TM x TN x 4 FMAs.
    let aRow = lid.y * TM;
    for (var kv: u32 = 0u; kv < AK_VECS; kv = kv + 1u) {

      let av0 = vec4<f32>(tileA[aRow + 0u][kv]);

      let av1 = vec4<f32>(tileA[aRow + 1u][kv]);

      let av2 = vec4<f32>(tileA[aRow + 2u][kv]);

      let av3 = vec4<f32>(tileA[aRow + 3u][kv]);

      let av4 = vec4<f32>(tileA[aRow + 4u][kv]);

      let av5 = vec4<f32>(tileA[aRow + 5u][kv]);

      let av6 = vec4<f32>(tileA[aRow + 6u][kv]);

      let av7 = vec4<f32>(tileA[aRow + 7u][kv]);


      let bv0 = vec4<f32>(tileB[kv * 4u + 0u][lid.x]);

      acc0 += vec4<f32>(av0.x) * bv0;

      acc1 += vec4<f32>(av1.x) * bv0;

      acc2 += vec4<f32>(av2.x) * bv0;

      acc3 += vec4<f32>(av3.x) * bv0;

      acc4 += vec4<f32>(av4.x) * bv0;

      acc5 += vec4<f32>(av5.x) * bv0;

      acc6 += vec4<f32>(av6.x) * bv0;

      acc7 += vec4<f32>(av7.x) * bv0;


      let bv1 = vec4<f32>(tileB[kv * 4u + 1u][lid.x]);

      acc0 += vec4<f32>(av0.y) * bv1;

      acc1 += vec4<f32>(av1.y) * bv1;

      acc2 += vec4<f32>(av2.y) * bv1;

      acc3 += vec4<f32>(av3.y) * bv1;

      acc4 += vec4<f32>(av4.y) * bv1;

      acc5 += vec4<f32>(av5.y) * bv1;

      acc6 += vec4<f32>(av6.y) * bv1;

      acc7 += vec4<f32>(av7.y) * bv1;


      let bv2 = vec4<f32>(tileB[kv * 4u + 2u][lid.x]);

      acc0 += vec4<f32>(av0.z) * bv2;

      acc1 += vec4<f32>(av1.z) * bv2;

      acc2 += vec4<f32>(av2.z) * bv2;

      acc3 += vec4<f32>(av3.z) * bv2;

      acc4 += vec4<f32>(av4.z) * bv2;

      acc5 += vec4<f32>(av5.z) * bv2;

      acc6 += vec4<f32>(av6.z) * bv2;

      acc7 += vec4<f32>(av7.z) * bv2;


      let bv3 = vec4<f32>(tileB[kv * 4u + 3u][lid.x]);

      acc0 += vec4<f32>(av0.w) * bv3;

      acc1 += vec4<f32>(av1.w) * bv3;

      acc2 += vec4<f32>(av2.w) * bv3;

      acc3 += vec4<f32>(av3.w) * bv3;

      acc4 += vec4<f32>(av4.w) * bv3;

      acc5 += vec4<f32>(av5.w) * bv3;

      acc6 += vec4<f32>(av6.w) * bv3;

      acc7 += vec4<f32>(av7.w) * bv3;


    }
    workgroupBarrier();
  }


  let yBatchBase = batch * M * N;
  let m0 = mBase + lid.y * TM;
  let n0 = nBase + lid.x * TN;





  store_out(m0 + 0u, n0 + 0u, yBatchBase, acc0.x);



  store_out(m0 + 0u, n0 + 1u, yBatchBase, acc0.y);



  store_out(m0 + 0u, n0 + 2u, yBatchBase, acc0.z);



  store_out(m0 + 0u, n0 + 3u, yBatchBase, acc0.w);






  store_out(m0 + 1u, n0 + 0u, yBatchBase, acc1.x);



  store_out(m0 + 1u, n0 + 1u, yBatchBase, acc1.y);



  store_out(m0 + 1u, n0 + 2u, yBatchBase, acc1.z);



  store_out(m0 + 1u, n0 + 3u, yBatchBase, acc1.w);






  store_out(m0 + 2u, n0 + 0u, yBatchBase, acc2.x);



  store_out(m0 + 2u, n0 + 1u, yBatchBase, acc2.y);



  store_out(m0 + 2u, n0 + 2u, yBatchBase, acc2.z);



  store_out(m0 + 2u, n0 + 3u, yBatchBase, acc2.w);






  store_out(m0 + 3u, n0 + 0u, yBatchBase, acc3.x);



  store_out(m0 + 3u, n0 + 1u, yBatchBase, acc3.y);



  store_out(m0 + 3u, n0 + 2u, yBatchBase, acc3.z);



  store_out(m0 + 3u, n0 + 3u, yBatchBase, acc3.w);






  store_out(m0 + 4u, n0 + 0u, yBatchBase, acc4.x);



  store_out(m0 + 4u, n0 + 1u, yBatchBase, acc4.y);



  store_out(m0 + 4u, n0 + 2u, yBatchBase, acc4.z);



  store_out(m0 + 4u, n0 + 3u, yBatchBase, acc4.w);






  store_out(m0 + 5u, n0 + 0u, yBatchBase, acc5.x);



  store_out(m0 + 5u, n0 + 1u, yBatchBase, acc5.y);



  store_out(m0 + 5u, n0 + 2u, yBatchBase, acc5.z);



