const BK: u32 = 16u;
const BM: u32 = 64u;
const BN: u32 = 64u;
const TM: u32 = 8u;
const TN: u32 = 4u;
const WG_X: u32 = 16u;
const WG_SIZE: u32 = 128u;
// Vector words per tile row: A groups K, B groups N.
const AK_VECS: u32 = BK / 4u;
const BN_VECS: u32 = BN / 4u;

// implicitIm2col leaves B unmaterialized. While staging a tile, the kernel
// decodes each (k, n) column-matrix coordinate into a raw NCHW input address.
// Overlapping windows may reread input values, trading address arithmetic and
// repeated input loads for writing and rereading an expanded column matrix.


















const CONV_KERNEL_H: u32 = 3u;
const CONV_KERNEL_W: u32 = 3u;
const CONV_KSIZE: u32 = CONV_KERNEL_H * CONV_KERNEL_W;
override CONV_STRIDE_H: u32 = 1u;
override CONV_STRIDE_W: u32 = 1u;
override CONV_DILATION_H: u32 = 1u;
override CONV_DILATION_W: u32 = 1u;
override CONV_PAD_TOP: i32 = 1;
override CONV_PAD_LEFT: i32 = 1;
override CONV_IN_H: u32 = 1u;
override CONV_IN_W: u32 = 1u;
override CONV_OUT_W: u32 = 1u;
override CONV_IN_CHANNELS: u32 = 1u;



fn store_out(m: u32, n: u32, yBase: u32, raw: f32) {
  if (m >= params.M || n >= params.N) {
    return;
  }
  var v = raw;

  if (params.has_bias != 0u) { v = v + f32(bias[m]); }

  y[yBase + m * params.N + n] = f32(v);
}


