    for (var linear = li; linear < BM * AK_VECS; linear += WG_SIZE) {
      let ar = linear / AK_VECS;
      let ac4 = linear % AK_VECS;
      let am = mBase + ar;
      let ak = kBase + ac4 * 4u;
      var av = vec4<f32>(f32(0.0));
