      let av2 = vec4<f32>(tileA[aRow + 2u][kv]);

      let av3 = vec4<f32>(tileA[aRow + 3u][kv]);

      let av4 = vec4<f32>(tileA[aRow + 4u][kv]);

      let av5 = vec4<f32>(tileA[aRow + 5u][kv]);

      let av6 = vec4<f32>(tileA[aRow + 6u][kv]);

