  y[yBase + m * params.N + n] = f16(v);
}


var<workgroup> tileA: array<array<vec4<f16>, AK_VECS>, BM>;
var<workgroup> tileB: array<array<vec4<f16>, BN_VECS>, BK>;





@compute @workgroup_size(16, 4, 1)
fn main(
  @builtin(workgroup_id) wg: vec3<u32>,
  @builtin(local_invocation_id) lid: vec3<u32>
) {
  let M = params.M;
  let K = params.K;
  let N = params.N;
  let mBase = wg.y * BM;
  let nBase = wg.x * BN;

  let batch = wg.z;


  let li = lid.y * WG_X + lid.x;

  // The statically named accumulator vectors form TM independent FMA chains.

  var acc0 = vec4<f32>(0.0);

  var acc1 = vec4<f32>(0.0);

  var acc2 = vec4<f32>(0.0);

  var acc3 = vec4<f32>(0.0);

  var acc4 = vec4<f32>(0.0);

  var acc5 = vec4<f32>(0.0);

  var acc6 = vec4<f32>(0.0);

  var acc7 = vec4<f32>(0.0);



  let numTiles = (K + BK - 1u) / BK;

  for (var kt: u32 = 0u; kt < numTiles; kt = kt + 1u) {

    let kBase = kt * BK;


    for (var linear = li; linear < BM * AK_VECS; linear += WG_SIZE) {
      let ar = linear / AK_VECS;
      let ac4 = linear % AK_VECS;
      let am = mBase + ar;
      let ak = kBase + ac4 * 4u;
      var av = vec4<f16>(f16(0.0));
      if (am < M) {
        let aBase = am * K + ak;
        if (ak + 3u < K) {
          av = vec4<f16>(f16(w[aBase]), f16(w[aBase + 1u]), f16(w[aBase + 2u]), f16(w[aBase + 3u]));
        } else {
          for (var t = 0u; t < 4u; t = t + 1u) {
            if (ak + t < K) {
              av[t] = f16(w[aBase + t]);
            }
          }
        }
      }
      tileA[ar][ac4] = av;
    }


    let bColVec = li / 4u;
    let bChunk = li % 4u;
    let bLocalK = bChunk * 8u;
    let bStartK = kBase + bLocalK;
    let bCol0 = nBase + bColVec * 4u;
    let bCols = vec4<u32>(bCol0, bCol0 + 1u, bCol0 + 2u, bCol0 + 3u);
    let inColumn = bCols < vec4<u32>(N);
    let ih0 = vec4<i32>((bCols / vec4<u32>(CONV_OUT_W)) * CONV_STRIDE_H) - vec4<i32>(CONV_PAD_TOP);
    let iw0 = vec4<i32>((bCols % vec4<u32>(CONV_OUT_W)) * CONV_STRIDE_W) - vec4<i32>(CONV_PAD_LEFT);
    var carriedK = bStartK;
    var carriedIc = carriedK / CONV_KSIZE;
    let carriedKq = carriedK % CONV_KSIZE;
    var carriedKh = carriedKq / CONV_KERNEL_W;
    var carriedKw = carriedKq % CONV_KERNEL_W;
    var carriedIh = ih0 + vec4<i32>(i32(carriedKh * CONV_DILATION_H));
    var carriedIw = iw0 + vec4<i32>(i32(carriedKw * CONV_DILATION_W));

    // Interior words can carry four addresses. Padding, the N tail, and the
    // final K tile retain the coordinate-checked loop below and publish exact
    // zeros.
    let interior = all(inColumn)
      && bStartK + 8u <= K
      && all(ih0 >= vec4<i32>(0))
      && all(ih0 + vec4<i32>(i32((CONV_KERNEL_H - 1u) * CONV_DILATION_H)) < vec4<i32>(i32(CONV_IN_H)))
      && all(iw0 >= vec4<i32>(0))
      && all(iw0 + vec4<i32>(i32((CONV_KERNEL_W - 1u) * CONV_DILATION_W)) < vec4<i32>(i32(CONV_IN_W)));
    if (interior) {
      let batchBase = batch * CONV_IN_CHANNELS * CONV_IN_H * CONV_IN_W;
      let colStep = i32(CONV_DILATION_W);
      let rowStep = i32(CONV_DILATION_H * CONV_IN_W);
      let planeStep = i32(CONV_IN_H * CONV_IN_W);
      let kwWrap = colStep * i32(CONV_KERNEL_W) - rowStep;
      let khWrap = rowStep * i32(CONV_KERNEL_H) - planeStep;
      var carriedAddress = vec4<i32>(i32(carriedIc) * planeStep) + carriedIh * vec4<i32>(i32(CONV_IN_W)) + carriedIw;
      for (var i = 0u; i < 8u; i = i + 1u) {
        tileB[bLocalK + i][bColVec] = vec4<f16>(

          f16(xm[batchBase + u32(carriedAddress.x)]),

          f16(xm[batchBase + u32(carriedAddress.y)]),

          f16(xm[batchBase + u32(carriedAddress.z)]),

          f16(xm[batchBase + u32(carriedAddress.w)])

        );
        carriedAddress = carriedAddress + vec4<i32>(colStep);
        carriedKw = carriedKw + 1u;
        if (carriedKw == CONV_KERNEL_W) {
          carriedKw = 0u;
          carriedAddress = carriedAddress - vec4<i32>(kwWrap);
          carriedKh = carriedKh + 1u;
          if (carriedKh == CONV_KERNEL_H) {
            carriedKh = 0u;
            carriedAddress = carriedAddress - vec4<i32>(khWrap);
          }
        }
      }
    } else {
      for (var i = 0u; i < 8u; i = i + 1u) {
        var carriedValue = vec4<f16>(f16(0.0));
        let carriedRow = (batch * CONV_IN_CHANNELS + carriedIc) * CONV_IN_H;
        let carriedOk = inColumn
          & (carriedIh >= vec4<i32>(0)) & (carriedIh < vec4<i32>(i32(CONV_IN_H)))
          & (carriedIw >= vec4<i32>(0)) & (carriedIw < vec4<i32>(i32(CONV_IN_W)));
        if (carriedK < K) {

          if (carriedOk.x) {
            carriedValue.x = f16(xm[(carriedRow + u32(carriedIh.x)) * CONV_IN_W + u32(carriedIw.x)]);
          }

          if (carriedOk.y) {
            carriedValue.y = f16(xm[(carriedRow + u32(carriedIh.y)) * CONV_IN_W + u32(carriedIw.y)]);
          }

          if (carriedOk.z) {
            carriedValue.z = f16(xm[(carriedRow + u32(carriedIh.z)) * CONV_IN_W + u32(carriedIw.z)]);
          }

          if (carriedOk.w) {
            carriedValue.w = f16(xm[(carriedRow + u32(carriedIh.w)) * CONV_IN_W + u32(carriedIw.w)]);
          }

        }
        tileB[bLocalK + i][bColVec] = carriedValue;
        carriedK = carriedK + 1u;
        carriedKw = carriedKw + 1u;
        carriedIw = carriedIw + vec4<i32>(i32(CONV_DILATION_W));
        if (carriedKw == CONV_KERNEL_W) {
          carriedKw = 0u;
          carriedIw = iw0;
          carriedKh = carriedKh + 1u;
          carriedIh = carriedIh + vec4<i32>(i32(CONV_DILATION_H));
          if (carriedKh == CONV_KERNEL_H) {
            carriedKh = 0u;
            carriedIh = ih0;
            carriedIc = carriedIc + 1u;
          }
        }
      }
    }

    workgroupBarrier();
    // One iteration consumes four K steps: TM vector words of A and four of B
    // cover TM x TN x 4 FMAs.
    let aRow = lid.y * TM;
    for (var kv: u32 = 0u; kv < AK_VECS; kv = kv + 1u) {

      let av0 = vec4<f32>(tileA[aRow + 0u][kv]);

      let av1 = vec4<f32>(tileA[aRow + 1u][kv]);

      let av2 = vec4<f32>(tileA[aRow + 2u][kv]);

      let av3 = vec4<f32>(tileA[aRow + 3u][kv]);

      let av4 = vec4<f32>(tileA[aRow + 4u][kv]);

      let av5 = vec4<f32>(tileA[aRow + 5u][kv]);

      let av6 = vec4<f32>(tileA[aRow + 6u][kv]);

      let av7 = vec4<f32>(tileA[aRow + 7u][kv]);


      let bv0 = vec4<f32>(tileB[kv * 4u + 0u][lid.x]);

      acc0 += vec4<f32>(av0.x) * bv0;

      acc1 += vec4<f32>(av1.x) * bv0;

      acc2 += vec4<f32>(av2.x) * bv0;

      acc3 += vec4<f32>(av3.x) * bv0;

      acc4 += vec4<f32>(av4.x) * bv0;

      acc5 += vec4<f32>(av5.x) * bv0;

      acc6 += vec4<f32>(av6.x) * bv0;

      acc7 += vec4<f32>(av7.x) * bv0;


      let bv1 = vec4<f32>(tileB[kv * 4u + 1u][lid.x]);

      acc0 += vec4<f32>(av0.y) * bv1;

      acc1 += vec4<f32>(av1.y) * bv1;

      acc2 += vec4<f32>(av2.y) * bv1;

      acc3 += vec4<f32>(av3.y) * bv1;

      acc4 += vec4<f32>(av4.y) * bv1;

      acc5 += vec4<f32>(av5.y) * bv1;

      acc6 += vec4<f32>(av6.y) * bv1;

      acc7 += vec4<f32>(av7.y) * bv1;


      let bv2 = vec4<f32>(tileB[kv * 4u + 2u][lid.x]);

      acc0 += vec4<f32>(av0.z) * bv2;

      acc1 += vec4<f32>(av1.z) * bv2;

      acc2 += vec4<f32>(av2.z) * bv2;

      acc3 += vec4<f32>(av3.z) * bv2;

      acc4 += vec4<f32>(av4.z) * bv2;

      acc5 += vec4<f32>(av5.z) * bv2;

      acc6 += vec4<f32>(av6.z) * bv2;

      acc7 += vec4<f32>(av7.z) * bv2;


      let bv3 = vec4<f32>(tileB[kv * 4u + 3u][lid.x]);

      acc0 += vec4<f32>(av0.w) * bv3;

      acc1 += vec4<f32>(av1.w) * bv3;

      acc2 += vec4<f32>(av2.w) * bv3;

      acc3 += vec4<f32>(av3.w) * bv3;

      acc4 += vec4<f32>(av4.w) * bv3;

      acc5 += vec4<f32>(av5.w) * bv3;

      acc6 += vec4<f32>(av6.w) * bv3;

      acc7 += vec4<f32>(av7.w) * bv3;


    }
    workgroupBarrier();
  }


  let yBatchBase = batch * M * N;
  let m0 = mBase + lid.y * TM;
  let n0 = nBase + lid.x * TN;





  store_out(m0 + 0u, n0 + 0u, yBatchBase, acc0.x);



  store_out(m0 + 0u, n0 + 1u, yBatchBase, acc0.y);



  store_out(m0 + 0u, n0 + 2u, yBatchBase, acc0.z);



  store_out(m0 + 0u, n0 + 3u, yBatchBase, acc0.w);






  store_out(m0 + 1u, n0 + 0u, yBatchBase, acc1.x);



  store_out(m0 + 1u, n0 + 1u, yBatchBase, acc1.y);



  store_out(m0 + 1u, n0 + 2u, yBatchBase, acc1.z);



  store_out(m0 + 1u, n0 + 3u, yBatchBase, acc1.w);






  store_out(m0 + 2u, n0 + 0u, yBatchBase, acc2.x);



  store_out(m0 + 2u, n0 + 1u, yBatchBase, acc2.y);



  store_out(m0 + 2u, n0 + 2u, yBatchBase, acc2.z);



  store_out(m0 + 2u, n0 + 3u, yBatchBase, acc2.w);






  store_out(m0 + 3u, n0 + 0u, yBatchBase, acc3.x);



  store_out(m0 + 3u, n0 + 1u, yBatchBase, acc3.y);



  store_out(m0 + 3u, n0 + 2u, yBatchBase, acc3.z);



  store_out(m0 + 3u, n0 + 3u, yBatchBase, acc3.w);






  store_out(m0 + 4u, n0 + 0u, yBatchBase, acc4.x);



  store_out(m0 + 4u, n0 + 1u, yBatchBase, acc4.y);



  store_out(m0 + 4u, n0 + 2u, yBatchBase, acc4.z);



  store_out(m0 + 4u, n0 + 3u, yBatchBase, acc4.w);






  store_out(m0 + 5u, n0 + 0u, yBatchBase, acc5.x);



  store_out(m0 + 5u, n0 + 1u, yBatchBase, acc5.y);



  store_out(m0 + 5u, n0 + 2u, yBatchBase, acc5.z);



  store_out(m0 + 5u, n0 + 3u, yBatchBase, acc5.w);






  store_out(m0 + 6u, n0 + 0u, yBatchBase, acc6.x);



  store_out(m0 + 6u, n0 + 1u, yBatchBase, acc6.y);



  store_out(m0 + 6u, n0 + 2u, yBatchBase, acc6.z);



  store_out(m0 + 6u, n0 + 3u, yBatchBase, acc6.w);






  store_out(m0 + 7u, n0 + 0u, yBatchBase, acc7.x);



  store_out(m0 + 7u, n0 + 1u, yBatchBase, acc7.y);



  store_out(m0 + 7u, n0 + 2u, yBatchBase, acc7.z);



  store_out(m0 + 7u, n0 + 3u, yBatchBase, acc7.w);


}
